#include <stdio.h>

int main() {
    int a[] = {2, 5, 8, 9, 12};
    int evens = 0, odds = 0;
    for (int i = 0; i < 5; i++) {
        if (a[i] % 2 == 0) {
            evens++;
        } else {
            odds++;
        }
    }
    printf("evens=%d odds=%d\n", evens, odds);
    return 0;
}
